    private final EmptyDatabase database = new EmptyDatabase();
    private final Rooms rooms = new Rooms(database.dataSource());
    private final ReservationStore store = new ReservationStore(database.dataSource());
    private final ReservationService service = new ReservationService(
            rooms, store, new PriceCalculator(), new EmailSender(new SentMessages(database.dataSource())));

    private Reservation book(int roomNumber, String checkIn, String checkOut, RatePlan plan) {
        Guest guest = new Guest("Bruno Lima", "bruno@example.com", "987.654.321-00");
        return service.create(new NewReservation(
                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), 1, plan));
    }

    @AfterEach
    void closeDatabase() {
        database.close();
    }

    @BeforeEach
    void someReservations() {
        Reservation april = book(201, "2027-04-01", "2027-04-03", RatePlan.STANDARD);
        Reservation lateMarch = book(101, "2027-03-30", "2027-04-02", RatePlan.NON_REFUNDABLE);
        Reservation suite = book(301, "2027-04-02", "2027-04-04", RatePlan.STANDARD);
        book(102, "2027-04-01", "2027-04-05", RatePlan.STANDARD); // never paid
        Reservation cancelled = book(202, "2027-04-01", "2027-04-02", RatePlan.STANDARD);
        service.confirm(april.id());
        service.confirm(lateMarch.id());
        service.confirm(suite.id());
        service.checkIn(suite.id());
        service.confirm(cancelled.id());
        service.cancel(cancelled.id());
    }

    @Test
    void occupancyListsThePaidReservationsCoveringTheNight() {
        String csv = new OccupancyReport(rooms, store).generate(LocalDate.of(2027, 4, 1));


    @Test
    void answersErrorsWithACode() throws Exception {
        HttpResponse<String> missingFields = post("/reservations", "{\"roomNumber\": 201}");
        assertEquals(400, missingFields.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(missingFields.body()).get("error").asText());

        assertEquals(400, post("/reservations", "not json").statusCode());
        assertEquals(400, post("/reservations", RESERVATION_JSON.replace("STANDARD", "VIP")).statusCode());
        assertEquals(404, get("/reservations/42").statusCode());
        assertEquals(404, get("/reservations/abc").statusCode());

        post("/reservations", RESERVATION_JSON);
        HttpResponse<String> taken = post("/reservations", RESERVATION_JSON);
        assertEquals(409, taken.statusCode());
        assertEquals("ROOM_UNAVAILABLE", json.readTree(taken.body()).get("error").asText());
    }

    @Test
    void servesTheReportsAsCsv() throws Exception {
        long id = json.readTree(post("/reservations", RESERVATION_JSON).body()).get("id").asLong();
        post("/reservations/" + id + "/confirmation", "");

        HttpResponse<String> occupancy = get("/reports/occupancy?date=2027-07-11");
        assertEquals(200, occupancy.statusCode());
        assertTrue(occupancy.headers().firstValue("Content-Type").orElse("").startsWith("text/csv"));
        assertTrue(occupancy.body().endsWith("total,1/5\n"));
        assertTrue(occupancy.body().startsWith("Pousada Maré Alta,occupancy,2027-07-11\n"));

        assertTrue(get("/reports/revenue?month=2027-07").body().endsWith("total,935.76\n"));
        assertTrue(get("/reports/tourism-tax?month=2027-07").body().endsWith("total,18.00\n"));
        assertTrue(get("/reports/rate-plans?month=2027-07").body().endsWith("total,1,935.76\n"));
        assertEquals(400, get("/reports/revenue?month=july").statusCode());
        assertEquals(400, get("/reports/occupancy").statusCode());
    }
}

